<?php
namespace App\Services;
use App\Exceptions\BusinessRuleException; use App\Models\BankAccount; use App\Models\BankTransaction; use App\Models\Cashbox; use App\Models\Expense; use App\Models\User; use App\Support\Dec; use Illuminate\Support\Facades\DB;
class FinanceService {
 public function balanceUnits(BankAccount $a): int { $sum=DB::table('bank_transactions')->where('status','approved')->where(fn($q)=>$q->where('from_account_id',$a->id)->orWhere('to_account_id',$a->id))->selectRaw("COALESCE(SUM(CASE WHEN to_account_id = ? THEN amount ELSE -amount END),0) AS bal",[$a->id])->value('bal'); return Dec::units($a->opening_balance,2)+Dec::units($sum??0,2); }
 public function approveBank(BankTransaction $tx, User $actor): BankTransaction { return DB::transaction(function() use($tx,$actor){ $tx=BankTransaction::whereKey($tx->id)->lockForUpdate()->firstOrFail(); if($tx->status!=='draft') throw new BusinessRuleException('Faqat qoralama bank operatsiyasini tasdiqlash mumkin.'); $amount=Dec::units($tx->amount,2); if($amount<=0) throw new BusinessRuleException('Summa musbat bo‘lishi kerak.'); $from=$tx->from_account_id?BankAccount::whereKey($tx->from_account_id)->lockForUpdate()->firstOrFail():null; $to=$tx->to_account_id?BankAccount::whereKey($tx->to_account_id)->lockForUpdate()->firstOrFail():null; if(in_array($tx->type,['withdrawal','transfer','bank_to_cash']) && (!$from || $this->balanceUnits($from)<$amount)) throw new BusinessRuleException('Bank hisobida mablag‘ yetarli emas.'); if($tx->type==='deposit' && !$to) throw new BusinessRuleException('Kirim uchun bank hisobi tanlang.'); if($tx->type==='withdrawal' && !$from) throw new BusinessRuleException('Chiqim uchun bank hisobi tanlang.'); if($tx->type==='transfer' && (!$from||!$to||$from->id===$to->id)) throw new BusinessRuleException('O‘tkazma uchun turli bank hisoblarini tanlang.'); if($tx->type==='transfer' && $from && $to && $from->currency!==$to->currency) throw new BusinessRuleException('Valyutasi turlicha hisoblar o‘rtasida konvertatsiya modulidan foydalaning.'); if($tx->type==='cash_to_bank' && (!$tx->cashbox_id || !$to || $from)) throw new BusinessRuleException('Kassadan bankka o‘tkazmada faqat kirim bank hisobi va kassa tanlanadi.'); if($tx->type==='bank_to_cash' && (!$tx->cashbox_id || !$from || $to)) throw new BusinessRuleException('Bankdan kassaga o‘tkazmada faqat chiqim bank hisobi va kassa tanlanadi.'); if($from && !$from->is_active || $to && !$to->is_active) throw new BusinessRuleException('Bank hisobi faol emas.');
 if(in_array($tx->type,['cash_to_bank','bank_to_cash'])) { $cash=Cashbox::whereKey($tx->cashbox_id)->lockForUpdate()->firstOrFail(); if(!$cash->is_active) throw new BusinessRuleException('Kassa faol emas.'); $this->cashMove($cash,$tx,$actor,$tx->type==='cash_to_bank'?'out':'in'); }
 $tx->status='approved'; $tx->approved_by=$actor->id; $tx->occurred_at=now(); $tx->save(); AuditLogger::log('bank.approve',$tx,null,['type'=>$tx->type,'amount'=>$tx->amount,'status'=>'approved'], 'success',$actor->id); return $tx->fresh(['fromAccount','toAccount','cashbox']); }); }
 private function cashMove(Cashbox $cash, BankTransaction $tx, User $actor, string $direction): void { $service=app(CashService::class); $balance=$service->balanceUnits($cash->id); $amount=Dec::units($tx->amount,2); if($direction==='out' && $balance<$amount) throw new BusinessRuleException('Kassada mablag‘ yetarli emas.'); $service->record($cash,$direction,$amount,'bank_transfer',$actor,null,'Bank operatsiyasi '.$tx->number,null,'bank_transaction',$tx->id); }
 public function approveExpense(Expense $expense, User $actor): Expense { return DB::transaction(function()use($expense,$actor){ $e=Expense::whereKey($expense->id)->lockForUpdate()->firstOrFail(); if($e->status!=='draft') throw new BusinessRuleException('Faqat qoralama xarajatni tasdiqlash mumkin.'); $amount=Dec::units($e->amount,2); if($e->payment_method==='bank'){ $a=BankAccount::whereKey($e->bank_account_id)->lockForUpdate()->firstOrFail(); if(!$a->is_active || $this->balanceUnits($a)<$amount) throw new BusinessRuleException('Bank hisobi faol emas yoki mablag‘ yetarli emas.'); $tx=BankTransaction::create(['number'=>'EXP-'.$e->number,'type'=>'expense','from_account_id'=>$a->id,'amount'=>$e->amount,'description'=>'Xarajat: '.$e->category.' — '.$e->description,'status'=>'approved','created_by'=>$actor->id,'approved_by'=>$actor->id,'occurred_at'=>now()]); $e->bank_transaction_id=$tx->id; } else { $cash=Cashbox::whereKey($e->cashbox_id)->lockForUpdate()->firstOrFail(); if(!$cash->is_active || app(CashService::class)->balanceUnits($cash->id)<$amount) throw new BusinessRuleException('Kassa faol emas yoki mablag‘ yetarli emas.'); app(CashService::class)->record($cash,'out',$amount,'expense',$actor,null,'Xarajat '.$e->number,null,'expense',$e->id); } $e->status='approved'; $e->approved_by=$actor->id; $e->save(); AuditLogger::log('expenses.approve',$e,null,['amount'=>$e->amount,'payment_method'=>$e->payment_method,'status'=>'approved'],'success',$actor->id); return $e->fresh(['bankAccount','cashbox','branch']); }); }
}
